"""Errors shared by the minisql implementation."""


class QueryError(Exception):
    """Raised for any problem with a query."""

"""Lexer, expression tree, and parser for minisql."""

from __future__ import annotations

import dataclasses
from typing import Any, Iterable, List, Optional

from ._errors import QueryError


KEYWORDS = frozenset(
    {
        "SELECT",
        "DISTINCT",
        "FROM",
        "WHERE",
        "GROUP",
        "BY",
        "HAVING",
        "ORDER",
        "ASC",
        "DESC",
        "LIMIT",
        "OFFSET",
        "AND",
        "OR",
        "NOT",
        "IS",
        "NULL",
        "IN",
        "BETWEEN",
        "LIKE",
        "AS",
        "TRUE",
        "FALSE",
    }
)

COMPARISON_OPS = frozenset({"<", "<=", ">", ">=", "=", "!=", "<>"})
ARITHMETIC_OPS = frozenset({"+", "-", "*", "/"})

AGGREGATES = frozenset({"COUNT", "SUM", "AVG", "MIN", "MAX"})

# Scalar function name -> (minimum arguments, maximum arguments or None)
SCALAR_ARITIES = {
    "LOWER": (1, 1),
    "UPPER": (1, 1),
    "LENGTH": (1, 1),
    "ABS": (1, 1),
    "ROUND": (1, 2),
    "COALESCE": (1, None),
}


@dataclasses.dataclass
class Token:
    kind: str
    value: Any
    start: int
    end: int


def tokenize(sql: str) -> List[Token]:
    """Turn SQL text into tokens."""
    tokens: List[Token] = []
    i = 0
    n = len(sql)

    while i < n:
        ch = sql[i]

        if ch.isspace():
            i += 1
            continue

        if ch == "'":
            start = i
            i += 1
            chars: List[str] = []
            while True:
                if i >= n:
                    raise QueryError("unterminated string literal")
                if sql[i] == "'":
                    if i + 1 < n and sql[i + 1] == "'":
                        chars.append("'")
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    chars.append(sql[i])
                    i += 1
            tokens.append(Token("STRING", "".join(chars), start, i))
            continue

        if ch == '"':
            start = i
            i += 1
            chars = []
            while True:
                if i >= n:
                    raise QueryError("unterminated quoted name")
                if sql[i] == '"':
                    if i + 1 < n and sql[i + 1] == '"':
                        chars.append('"')
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    chars.append(sql[i])
                    i += 1
            tokens.append(Token("QNAME", "".join(chars), start, i))
            continue

        if ch.isdigit() or (ch == "." and i + 1 < n and sql[i + 1].isdigit()):
            start = i
            if ch == ".":
                i += 1
                while i < n and sql[i].isdigit():
                    i += 1
            else:
                while i < n and sql[i].isdigit():
                    i += 1
                if i < n and sql[i] == ".":
                    i += 1
                    while i < n and sql[i].isdigit():
                        i += 1
            tokens.append(Token("NUMBER", sql[start:i], start, i))
            continue

        if ch.isalpha() or ch == "_":
            start = i
            i += 1
            while i < n and (sql[i].isalnum() or sql[i] == "_"):
                i += 1
            word = sql[start:i]
            upper = word.upper()
            if upper in KEYWORDS:
                tokens.append(Token("KEYWORD", upper, start, i))
            else:
                tokens.append(Token("NAME", word, start, i))
            continue

        two = sql[i : i + 2]
        if two in ("<=", ">=", "<>", "!=", "||"):
            tokens.append(Token("OP", two, i, i + 2))
            i += 2
            continue
        if ch in "=<>+-*/(),;":
            tokens.append(Token("OP", ch, i, i + 1))
            i += 1
            continue

        raise QueryError("unexpected character %r in query" % ch)

    tokens.append(Token("EOF", None, n, n))
    return tokens


# ---------------------------------------------------------------------------
# Expression tree


@dataclasses.dataclass
class Literal:
    value: Any
    start: int
    end: int


@dataclasses.dataclass
class Column:
    name: str
    start: int
    end: int
    index: Optional[int] = None


@dataclasses.dataclass
class Unary:
    op: str
    operand: Any
    start: int
    end: int


@dataclasses.dataclass
class Binary:
    op: str
    left: Any
    right: Any
    start: int
    end: int


@dataclasses.dataclass
class IsNull:
    operand: Any
    negated: bool
    start: int
    end: int


@dataclasses.dataclass
class InList:
    operand: Any
    items: List[Any]
    negated: bool
    start: int
    end: int


@dataclasses.dataclass
class Between:
    operand: Any
    low: Any
    high: Any
    negated: bool
    start: int
    end: int


@dataclasses.dataclass
class Like:
    operand: Any
    pattern: Any
    negated: bool
    start: int
    end: int


@dataclasses.dataclass
class Call:
    name: str
    args: List[Any]
    star: bool
    start: int
    end: int


@dataclasses.dataclass
class SelectItem:
    expr: Any
    alias: Optional[str] = None


@dataclasses.dataclass
class OrderItem:
    expr: Any
    descending: bool = False


@dataclasses.dataclass
class Query:
    sql: str
    distinct: bool
    star: bool
    select: List[SelectItem]
    table: str
    where: Optional[Any] = None
    group_by: List[Any] = dataclasses.field(default_factory=list)
    having: Optional[Any] = None
    order_by: List[OrderItem] = dataclasses.field(default_factory=list)
    limit: Optional[int] = None
    offset: Optional[int] = None


def children(node: Any) -> Iterable[Any]:
    """Yield the direct sub-expressions of *node*."""
    if isinstance(node, Unary):
        yield node.operand
    elif isinstance(node, IsNull):
        yield node.operand
    elif isinstance(node, Binary):
        yield node.left
        yield node.right
    elif isinstance(node, InList):
        yield node.operand
        for item in node.items:
            yield item
    elif isinstance(node, Between):
        yield node.operand
        yield node.low
        yield node.high
    elif isinstance(node, Like):
        yield node.operand
        yield node.pattern
    elif isinstance(node, Call):
        for arg in node.args:
            yield arg


def contains_aggregate(node: Any) -> bool:
    """Return whether *node* contains an aggregate function call."""
    if isinstance(node, Call) and node.name.upper() in AGGREGATES:
        return True
    return any(contains_aggregate(child) for child in children(node))


def expr_equal(a: Any, b: Any) -> bool:
    """Structural equality of expressions, ignoring source positions."""
    if a is b:
        return True
    if type(a) is not type(b):
        return False
    if isinstance(a, Literal):
        return type(a.value) is type(b.value) and a.value == b.value
    if isinstance(a, Column):
        return a.name.casefold() == b.name.casefold()
    if isinstance(a, Unary):
        return a.op == b.op and expr_equal(a.operand, b.operand)
    if isinstance(a, Binary):
        return (
            a.op == b.op
            and expr_equal(a.left, b.left)
            and expr_equal(a.right, b.right)
        )
    if isinstance(a, IsNull):
        return a.negated == b.negated and expr_equal(a.operand, b.operand)
    if isinstance(a, InList):
        return (
            a.negated == b.negated
            and expr_equal(a.operand, b.operand)
            and len(a.items) == len(b.items)
            and all(expr_equal(x, y) for x, y in zip(a.items, b.items))
        )
    if isinstance(a, Between):
        return (
            a.negated == b.negated
            and expr_equal(a.operand, b.operand)
            and expr_equal(a.low, b.low)
            and expr_equal(a.high, b.high)
        )
    if isinstance(a, Like):
        return (
            a.negated == b.negated
            and expr_equal(a.operand, b.operand)
            and expr_equal(a.pattern, b.pattern)
        )
    if isinstance(a, Call):
        return (
            a.name.upper() == b.name.upper()
            and a.star == b.star
            and len(a.args) == len(b.args)
            and all(expr_equal(x, y) for x, y in zip(a.args, b.args))
        )
    return False


# ---------------------------------------------------------------------------
# Parser


class Parser:
    def __init__(self, sql: str):
        self.sql = sql
        self.tokens = tokenize(sql)
        self.pos = 0

    # -- token helpers -----------------------------------------------------

    def _peek(self, offset: int = 0) -> Token:
        index = self.pos + offset
        if index >= len(self.tokens):
            return self.tokens[-1]
        return self.tokens[index]

    def _advance(self) -> Token:
        token = self._peek()
        if token.kind != "EOF":
            self.pos += 1
        return token

    def _check_keyword(self, word: str) -> bool:
        token = self._peek()
        return token.kind == "KEYWORD" and token.value == word

    def _match_keyword(self, word: str) -> bool:
        if self._check_keyword(word):
            self.pos += 1
            return True
        return False

    def _expect_keyword(self, word: str) -> Token:
        if self._check_keyword(word):
            return self._advance()
        raise self._error("expected %s" % word)

    def _check_op(self, op: str) -> bool:
        token = self._peek()
        return token.kind == "OP" and token.value == op

    def _match_op(self, op: str) -> bool:
        if self._check_op(op):
            self.pos += 1
            return True
        return False

    def _expect_op(self, op: str) -> Token:
        if self._check_op(op):
            return self._advance()
        raise self._error("expected %r" % op)

    def _error(self, message: str) -> QueryError:
        token = self._peek()
        if token.kind == "EOF":
            return QueryError("%s at end of query" % message)
        text = self.sql[token.start : token.end]
        return QueryError("%s near %r" % (message, text))

    def _expect_name(self, what: str = "a name") -> Token:
        token = self._peek()
        if token.kind in ("NAME", "QNAME"):
            return self._advance()
        raise self._error("expected %s" % what)

    # -- top level ---------------------------------------------------------

    def parse(self) -> Query:
        self._expect_keyword("SELECT")

        distinct = self._match_keyword("DISTINCT")

        star = False
        select: List[SelectItem] = []
        if self._match_op("*"):
            star = True
        else:
            select.append(self._parse_select_item())
            while self._match_op(","):
                select.append(self._parse_select_item())

        self._expect_keyword("FROM")
        table = self._expect_name("a table name").value

        where = None
        if self._match_keyword("WHERE"):
            where = self.parse_expression()

        group_by: List[Any] = []
        if self._match_keyword("GROUP"):
            self._expect_keyword("BY")
            group_by.append(self.parse_expression())
            while self._match_op(","):
                group_by.append(self.parse_expression())

        having = None
        if self._match_keyword("HAVING"):
            having = self.parse_expression()

        order_by: List[OrderItem] = []
        if self._match_keyword("ORDER"):
            self._expect_keyword("BY")
            order_by.append(self._parse_order_item())
            while self._match_op(","):
                order_by.append(self._parse_order_item())

        limit = None
        offset = None
        if self._match_keyword("LIMIT"):
            limit = self._parse_nonnegative_integer("LIMIT")
            if self._match_keyword("OFFSET"):
                offset = self._parse_nonnegative_integer("OFFSET")

        self._match_op(";")

        if self._peek().kind != "EOF":
            raise self._error("unexpected token")

        return Query(
            sql=self.sql,
            distinct=distinct,
            star=star,
            select=select,
            table=table,
            where=where,
            group_by=group_by,
            having=having,
            order_by=order_by,
            limit=limit,
            offset=offset,
        )

    def _parse_select_item(self) -> SelectItem:
        expr = self.parse_expression()
        alias = None
        if self._match_keyword("AS"):
            alias = self._expect_name("an alias").value
        elif self._peek().kind in ("NAME", "QNAME"):
            # An unquoted or quoted name directly after an expression is an
            # implicit alias.
            alias = self._advance().value
        return SelectItem(expr=expr, alias=alias)

    def _parse_order_item(self) -> OrderItem:
        expr = self.parse_expression()
        descending = False
        if self._match_keyword("DESC"):
            descending = True
        else:
            self._match_keyword("ASC")
        return OrderItem(expr=expr, descending=descending)

    def _parse_nonnegative_integer(self, context: str) -> int:
        token = self._peek()
        if token.kind != "NUMBER" or "." in token.value:
            raise self._error("expected an integer after %s" % context)
        self.pos += 1
        return int(token.value)

    # -- expressions -------------------------------------------------------

    def parse_expression(self) -> Any:
        return self._parse_or()

    def _parse_or(self) -> Any:
        node = self._parse_and()
        while self._match_keyword("OR"):
            right = self._parse_and()
            node = Binary("OR", node, right, node.start, right.end)
        return node

    def _parse_and(self) -> Any:
        node = self._parse_not()
        while self._match_keyword("AND"):
            right = self._parse_not()
            node = Binary("AND", node, right, node.start, right.end)
        return node

    def _parse_not(self) -> Any:
        if self._match_keyword("NOT"):
            token = self.tokens[self.pos - 1]
            operand = self._parse_not()
            return Unary("NOT", operand, token.start, operand.end)
        return self._parse_comparison()

    def _parse_comparison(self) -> Any:
        left = self._parse_additive()
        token = self._peek()

        if token.kind == "OP" and token.value in COMPARISON_OPS:
            self.pos += 1
            right = self._parse_additive()
            return Binary(token.value, left, right, left.start, right.end)

        if token.kind == "KEYWORD" and token.value == "IS":
            self.pos += 1
            negated = self._match_keyword("NOT")
            null_token = self._expect_keyword("NULL")
            return IsNull(left, negated, left.start, null_token.end)

        if token.kind == "KEYWORD" and token.value == "NOT":
            following = self._peek(1)
            if following.kind == "KEYWORD" and following.value in (
                "IN",
                "BETWEEN",
                "LIKE",
            ):
                self.pos += 1
                return self._parse_predicate(left, True)

        if token.kind == "KEYWORD" and token.value in ("IN", "BETWEEN", "LIKE"):
            return self._parse_predicate(left, False)

        return left

    def _parse_predicate(self, left: Any, negated: bool) -> Any:
        token = self._advance()
        word = token.value

        if word == "IN":
            self._expect_op("(")
            items = [self.parse_expression()]
            while self._match_op(","):
                items.append(self.parse_expression())
            close = self._expect_op(")")
            return InList(left, items, negated, left.start, close.end)

        if word == "BETWEEN":
            low = self._parse_additive()
            self._expect_keyword("AND")
            high = self._parse_additive()
            return Between(left, low, high, negated, left.start, high.end)

        # LIKE
        pattern = self._parse_additive()
        return Like(left, pattern, negated, left.start, pattern.end)

    def _parse_additive(self) -> Any:
        node = self._parse_multiplicative()
        while True:
            token = self._peek()
            if token.kind == "OP" and token.value in ("+", "-", "||"):
                self.pos += 1
                right = self._parse_multiplicative()
                node = Binary(token.value, node, right, node.start, right.end)
            else:
                return node

    def _parse_multiplicative(self) -> Any:
        node = self._parse_unary()
        while True:
            token = self._peek()
            if token.kind == "OP" and token.value in ("*", "/"):
                self.pos += 1
                right = self._parse_unary()
                node = Binary(token.value, node, right, node.start, right.end)
            else:
                return node

    def _parse_unary(self) -> Any:
        if self._check_op("-"):
            token = self._advance()
            operand = self._parse_unary()
            return Unary("-", operand, token.start, operand.end)
        return self._parse_primary()

    def _parse_primary(self) -> Any:
        token = self._peek()

        if token.kind == "NUMBER":
            self.pos += 1
            if "." in token.value:
                return Literal(float(token.value), token.start, token.end)
            return Literal(int(token.value), token.start, token.end)

        if token.kind == "STRING":
            self.pos += 1
            return Literal(token.value, token.start, token.end)

        if token.kind == "KEYWORD":
            if token.value == "NULL":
                self.pos += 1
                return Literal(None, token.start, token.end)
            if token.value == "TRUE":
                self.pos += 1
                return Literal(True, token.start, token.end)
            if token.value == "FALSE":
                self.pos += 1
                return Literal(False, token.start, token.end)
            raise self._error("expected an expression")

        if token.kind == "NAME":
            self.pos += 1
            if self._check_op("("):
                return self._parse_call(token)
            return Column(token.value, token.start, token.end)

        if token.kind == "QNAME":
            self.pos += 1
            return Column(token.value, token.start, token.end)

        if token.kind == "OP" and token.value == "(":
            open_token = self._advance()
            node = self.parse_expression()
            close_token = self._expect_op(")")
            # Preserve the written form of a parenthesised expression for use
            # as an output column name.
            node.start = open_token.start
            node.end = close_token.end
            return node

        raise self._error("expected an expression")

    def _parse_call(self, name_token: Token) -> Any:
        self._expect_op("(")
        star = False
        args: List[Any] = []

        if self._match_op("*"):
            star = True
        elif not self._check_op(")"):
            args.append(self.parse_expression())
            while self._match_op(","):
                args.append(self.parse_expression())

        close_token = self._expect_op(")")
        return Call(
            name_token.value,
            args,
            star,
            name_token.start,
            close_token.end,
        )

"""Table loading, validation, and query evaluation for minisql."""

from __future__ import annotations

import csv
import os
import re
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext
from functools import cmp_to_key, lru_cache
from typing import Any, List, NamedTuple, Optional, Tuple

from ._errors import QueryError
from ._sql import (
    AGGREGATES,
    SCALAR_ARITIES,
    Between,
    Binary,
    Call,
    Column,
    InList,
    IsNull,
    Like,
    Literal,
    Query,
    Unary,
    children,
    contains_aggregate,
    expr_equal,
)


class Result(NamedTuple):
    """The result of running a query."""

    columns: List[str]
    rows: List[Tuple[Any, ...]]


class Table:
    __slots__ = ("name", "headers", "rows", "lookup")

    def __init__(self, name: str, headers: List[str], rows: List[Tuple[Any, ...]]):
        self.name = name
        self.headers = headers
        self.rows = rows
        self.lookup = {}
        for index, header in enumerate(headers):
            self.lookup.setdefault(header.casefold(), index)

    def column_index(self, name: str) -> int:
        try:
            return self.lookup[name.casefold()]
        except KeyError:
            raise QueryError("unknown column: %s" % name) from None


_INTEGER_RE = re.compile(r"-?[0-9]+")
_DECIMAL_RE = re.compile(r"-?(?:[0-9]+\.[0-9]*|[0-9]*\.[0-9]+)")


def _parse_field(field: str) -> Any:
    if field == "":
        return None
    if _INTEGER_RE.fullmatch(field):
        return int(field)
    if _DECIMAL_RE.fullmatch(field):
        return float(field)
    return field


def load_table(directory: Any, name: str) -> Table:
    path = os.path.join(os.fspath(directory), name + ".csv")
    try:
        with open(path, "r", encoding="utf-8", newline="") as handle:
            reader = csv.reader(handle)
            try:
                headers = next(reader)
            except StopIteration:
                raise QueryError("table %r is empty" % name) from None

            rows: List[Tuple[Any, ...]] = []
            width = len(headers)
            for line_number, fields in enumerate(reader, start=2):
                if len(fields) > width:
                    raise QueryError(
                        "table %r row %d has more fields than the header"
                        % (name, line_number)
                    )
                if len(fields) < width:
                    fields = fields + [""] * (width - len(fields))
                rows.append(tuple(_parse_field(field) for field in fields))
    except QueryError:
        raise
    except (OSError, UnicodeError) as exc:
        raise QueryError("cannot read table %r: %s" % (name, exc)) from exc

    return Table(name, headers, rows)


# ---------------------------------------------------------------------------
# Validation


def _validate_functions(node: Any, in_aggregate: bool = False) -> None:
    if isinstance(node, Call):
        name = node.name.upper()
        if name in AGGREGATES:
            if in_aggregate:
                raise QueryError("aggregates cannot be nested")
            if node.star:
                if name != "COUNT":
                    raise QueryError("%s does not accept *" % node.name)
            elif len(node.args) != 1:
                raise QueryError(
                    "%s takes exactly one argument" % node.name
                )
            for arg in node.args:
                _validate_functions(arg, True)
            return

        if node.star:
            raise QueryError("function %s does not accept *" % node.name)
        if name not in SCALAR_ARITIES:
            raise QueryError("unknown function: %s" % node.name)
        minimum, maximum = SCALAR_ARITIES[name]
        count = len(node.args)
        if count < minimum or (maximum is not None and count > maximum):
            if maximum is None:
                expected = "at least %d" % minimum
            elif minimum == maximum:
                expected = "exactly %d" % minimum
            else:
                expected = "%d to %d" % (minimum, maximum)
            raise QueryError(
                "%s takes %s argument%s"
                % (node.name, expected, "" if minimum == 1 and maximum == 1 else "s")
            )
        for arg in node.args:
            _validate_functions(arg, in_aggregate)
        return

    for child in children(node):
        _validate_functions(child, in_aggregate)


def _resolve_columns(node: Any, table: Table) -> None:
    if isinstance(node, Column):
        node.index = table.column_index(node.name)
        return
    for child in children(node):
        _resolve_columns(child, table)


def _check_grouped(node: Any, group_expressions: List[Any]) -> None:
    if isinstance(node, Call) and node.name.upper() in AGGREGATES:
        return
    for group_expression in group_expressions:
        if expr_equal(node, group_expression):
            return
    if isinstance(node, Column):
        raise QueryError(
            "column %r must appear in GROUP BY or be used in an aggregate"
            % node.name
        )
    for child in children(node):
        _check_grouped(child, group_expressions)


def _output_name(item: Any, table: Table, sql: str) -> str:
    if item.alias is not None:
        return item.alias
    expression = item.expr
    if isinstance(expression, Column):
        index = table.column_index(expression.name)
        expression.index = index
        return table.headers[index]
    return sql[expression.start : expression.end]


def _order_mode(expression: Any, output_columns: List[str]) -> Tuple[str, Optional[int]]:
    if isinstance(expression, Literal) and type(expression.value) is int:
        number = expression.value
        if number < 1 or number > len(output_columns):
            raise QueryError("ORDER BY column number %d is out of range" % number)
        return ("output", number - 1)

    if isinstance(expression, Column):
        for index, name in enumerate(output_columns):
            if name == expression.name:
                return ("output", index)
        folded = expression.name.casefold()
        for index, name in enumerate(output_columns):
            if name.casefold() == folded:
                return ("output", index)

    return ("expr", None)


# ---------------------------------------------------------------------------
# Evaluation


class _Context:
    __slots__ = ("row", "group")

    def __init__(self, row: Optional[Tuple[Any, ...]], group: Optional[List[Any]]):
        self.row = row
        self.group = group


def _kind(value: Any) -> str:
