    right_kind = _kind(right)

    if left_kind == "number" and right_kind == "number":
        if left < right:
            return -1
        if left > right:
            return 1
        return 0

    if left_kind == "string" and right_kind == "string":
        if left < right:
            return -1
        if left > right:
            return 1
        return 0

    if left_kind == "boolean" and right_kind == "boolean":
