    argument = node.args[0]
    values: List[Any] = []
    for row in context.group:
        value = _eval(argument, _Context(row, None))
        if value is not None:
            values.append(value)

    if not values:
        return None

    if name == "SUM":
        total = None
        for value in values:
            _number(value, "SUM")
            total = value if total is None else total + value
        return total

    if name == "AVG":
        total = None
        for value in values:
            _number(value, "AVG")
